import {seed, TASKS, VERSION, hoursSince, visibleState, event, hasConflict, summaryFor} from './engine.js';
const $ = s => document.querySelector(s);
const KEY='carebridge-demo-v1';
let state; try {state=JSON.parse(localStorage.getItem(KEY));}catch{} if(!state||state.version!==VERSION||!Array.isArray(state.patients)) state=seed();
let session; try {session=JSON.parse(sessionStorage.getItem('carebridge-session'));}catch{};
const profiles={nurse:{role:'nurse',name:'Emma Davis',title:'Nurse coordinator',initials:'ED',color:'sand',personId:'n1'},caregiver:{role:'caregiver',name:'Maya Patel',title:'CNA student · supervised',initials:'MP',color:'lavender',personId:'c1'},patient:{role:'patient',name:'Eleanor Bennett',title:'Patient',initials:'EB',color:'peach',personId:'p1'}};
if(!session||!profiles[session.role])session=null;
let page='overview',selectedPatient=null,filter='all',visitFilter='all',search='',loginRole='nurse',mobileOpen=false,toastTimer,lastFocus;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2 M8 14h2 M14 14h2 M8 18h2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',logout:'M9 5H4v14h5 M9 12h12 M17 8l4 4-4 4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',left:'M19 12H5 M10 7l-5 5 5 5',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',check:'M5 12l4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sparkles:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',file:'M14 2H5v20h14V7z M14 2v5h5 M8 12h8 M8 16h6',home:'M3 10l9-7 9 7v11h-7v-7h-4v7H3z',menu:'M4 6h16 M4 12h16 M4 18h16',close:'M6 6l12 12 M18 6L6 18',briefcase:'M8 6V3h8v3 M3 6h18v15H3z M3 12c6 3 12 3 18 0 M10 12h4v4h-4z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',message:'M21 11a8 8 0 0 1-8 8H5l-4 3V5a3 3 0 0 1 3-3h9a8 8 0 0 1 8 9 M6 8h9 M6 12h6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'M12 3L1 21h22z M12 9v5 M12 17h.01',leaf:'M20 3C5 1 1 9 6 16s17 0 14-13 M5 21L16 8',phone:'M5 3h4l2 6-3 2c1 3 2 4 5 5l2-3 6 2v4c0 5-19-1-19-13z',checkcircle:'M9 12l2 2 5-6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.heart}"/></svg>`;
const logo=()=>`<div class="logo"><span class="logo-mark"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M5 21Q16 4 27 21M5 21v7m22-7v7M16 13v15" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg></span>CareBridge<span style="font-size:13px;color:#a1bd82;margin-left:-6px">✳</span></div>`;
const art=()=>`<svg class="home-art" viewBox="0 0 260 180" fill="none" aria-hidden="true"><circle cx="151" cy="96" r="69" fill="#dce8cc"/><ellipse cx="145" cy="161" rx="101" ry="8" fill="#d1dfbf"/><path d="M76 88l62-50 62 50" stroke="#617e53" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/><path d="M87 84l51-42 51 42v72H87z" fill="#fafaf0"/><path d="M76 88l62-50 62 50" stroke="#658556" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/><rect x="128" y="107" width="28" height="49" rx="14" fill="#92ab78"/><circle cx="150" cy="136" r="2" fill="#f1f3e4"/><rect x="101" y="99" width="18" height="24" rx="4" fill="#dce7ce"/><path d="M110 99v24m-9-12h18" stroke="#fafaf0" stroke-width="2"/><rect x="164" y="99" width="14" height="24" rx="4" fill="#dce7ce"/><path d="M171 99v24" stroke="#fafaf0" stroke-width="2"/><path d="M208 152v-40M208 135c-20-1-20-19-20-19 18-1 20 19 20 19M208 126c20-1 20-19 20-19-18-1-20 19-20 19" stroke="#829a65" stroke-width="2" fill="#acc193"/><path d="M198 150h21l-3 12h-15z" fill="#b99473"/><path d="M56 146v-27" stroke="#829a65" stroke-width="2"/><ellipse cx="55" cy="117" rx="13" ry="21" fill="#a1b582"/><path d="M45 144h22l-3 15H48z" fill="#c5d1ad"/><circle cx="211" cy="47" r="20" fill="#fcfcf2"/><path d="M201 46c0-6 7-7 10-2 4-5 11-4 11 2 0 5-11 12-11 12s-10-7-10-12" fill="#c5d4a6"/><path d="M45 66h11m-5-5v11" stroke="#a6bb8d" stroke-width="2" stroke-linecap="round"/><circle cx="194" cy="22" r="3" fill="#c9d8b5"/><circle cx="73" cy="36" r="3" fill="#c9d8b5"/></svg>`;
const avatar=(p,size='')=>`<span class="avatar ${p?.color||'mint'} ${size}">${escape(p?.initials||'?')}</span>`;
const person=(p,sub='',size='')=>`<div class="person">${avatar(p,size)}<div><strong>${escape(p?.name||'Not assigned')}</strong>${sub?`<small>${escape(sub)}</small>`:''}</div></div>`;
const status=(s,label)=>`<span class="status ${s}"><span class="dot ${s==='new'||s==='attention'?'amber':''}"></span>${escape(label||({'in-progress':'In progress',scheduled:'Scheduled',completed:'Completed',new:'Needs attention',acknowledged:'In review',resolved:'Resolved',cancelled:'Cancelled'}[s]||s))}</span>`;
const button=(label,action,style='primary',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
const initials=name=>name.trim().split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase();
const pById=id=>state.patients.find(p=>p.id===id);
const cById=id=>state.caregivers.find(c=>c.id===id);
const view=()=>visibleState(state,session);
const isNurse=()=>session?.role==='nurse';
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateText=(date,options={month:'short',day:'numeric'})=>new Date(date?.length===10?date+'T12:00:00':date).toLocaleDateString('en-US',options);
const timeText=time=>{const [h,m]=time.split(':');return `${Number(h)%12||12}:${m} ${Number(h)<12?'AM':'PM'}`};
const relative=at=>{const min=Math.max(0,Math.floor((Date.now()-new Date(at))/60000));return min<1?'Just now':min<60?`${min} min ago`:min<1440?`${Math.floor(min/60)} hr ago`:dateText(at)};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Changes will last only for this session.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function login(){const selected=profiles[loginRole];$('#app').innerHTML=`<div class="login-shell"><section class="login-story">${logo()}<div class="login-story-body"><div class="eyebrow">THE FIRST 72 HOURS, TOGETHER</div><h1>A softer landing.<br>A stronger <em>start.</em></h1><p>A little support makes a big difference. Connecting hospital teams, caregivers, and the people coming home.</p>${art()}</div><div class="login-quote">${icon('heart')} Thoughtful care, beyond the hospital doors.</div></section><main class="login-main"><div class="login-form"><span class="login-badge"><span class="dot"></span> INTERACTIVE DEMO · FICTIONAL DATA</span><h2>Welcome to CareBridge.</h2><p>One connected care team.<br>Choose a demo profile to explore your workspace.</p>${Object.entries(profiles).map(([key,p])=>`<button class="login-role ${key===loginRole?'selected':''}" data-action="select-role" data-id="${key}" aria-pressed="${key===loginRole}"><span class="role-icon">${icon(key==='nurse'?'briefcase':key==='caregiver'?'heart':'home')}</span><span><strong>${key==='nurse'?'Hospital & nurse':key==='caregiver'?'Caregiver / CNA student':'Patient & family'}</strong><small>${escape(p.name)} · ${key==='nurse'?'Coordinate care':key==='caregiver'?'Make every visit count':'Your recovery, at a glance'}</small></span><span class="radio"></span></button>`).join('')}${button(`Continue as ${selected.name.split(' ')[0]} ${icon('arrow')}`,'login')}<p class="login-disclaimer">Demo profiles preview each role; they are not secure accounts.<br>Changes stay in this browser. Please use fictional information.</p></div></main></div>`}
function render(){if(!session){login();return}const navs=[['overview','grid','Overview'],['patients','users',isNurse()?'Patients':session.role==='caregiver'?'My patients':'My care plan'],['visits','calendar','Visits'],...(session.role!=='patient'?[['team','heart','Care team']]:[]),['alerts','bell',isNurse()?'Care alerts':'My concerns']];const open=view().alerts.filter(a=>a.status!=='resolved').length;const title=navs.find(n=>n[0]===page)?.[2]||({settings:'Settings',detail:'Patient overview',search:'Search results'}[page]);$('#app').innerHTML=`<div class="mobile-scrim ${mobileOpen?'open':''}" data-action="toggle-menu"></div><aside class="sidebar ${mobileOpen?'open':''}">${logo()}<div class="workspace-label"><span></span>${session.role==='nurse'?'HOSPITAL WORKSPACE':session.role==='caregiver'?'CAREGIVER WORKSPACE':'YOUR CARE WORKSPACE'}</div><nav class="nav" aria-label="Main navigation">${navs.map(([key,ic,label])=>`<button data-action="nav" data-id="${key}" class="${page===key||(key==='patients'&&page==='detail')?'active':''}" ${page===key?'aria-current="page"':''}>${icon(ic)}${label}${key==='patients'&&session.role!=='patient'?`<span class="count">${view().patients.length}</span>`:key==='alerts'&&open?`<span class="count">${open}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><div class="little-arc"></div>${icon('heart','heart')}<h4>Small moments. Better care.</h4><p>Your support makes the journey home a little easier.</p></div><nav class="nav" aria-label="Account"><button data-action="nav" data-id="settings" class="${page==='settings'?'active':''}">${icon('settings')}Settings</button></nav><div class="sidebar-footer">${avatar(session)}<div><strong>${escape(session.name)}</strong><small>${escape(session.title)}</small></div><button class="icon-btn" data-action="logout" aria-label="Sign out and change demo profile" title="Change demo profile">${icon('logout')}</button></div></div></aside><div class="app-main"><header class="topbar"><button class="icon-btn mobile-menu" data-action="toggle-menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="crumb">Workspace ${icon('chevron')}<strong>${escape(title)}</strong></div><div class="top-actions"><form class="search-box" id="search-form" role="search">${icon('search')}<input id="global-search" aria-label="Search patients" placeholder="Search patients…" value="${escape(search)}"><kbd>↵</kbd></form><span class="demo-label">DEMO WORKSPACE</span><button class="icon-btn" data-action="nav" data-id="alerts" aria-label="View care alerts">${icon('bell')}${open?'<span class="notification-dot"></span>':''}</button><button class="icon-btn top-avatar" data-action="nav" data-id="settings" aria-label="Profile settings">${avatar(session)}</button></div></header><main class="content" id="main-content">${pageContent()}<footer class="footer"><span>${icon('leaf')} A little care goes a long way.</span><span>Fictional patients · Saved in this browser</span></footer></main></div>`;}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function pageContent(){return ({overview:dashboard,patients:patientsPage,visits:visitsPage,team:teamPage,alerts:alertsPage,settings:settingsPage,detail:detailPage,search:patientsPage}[page]||dashboard)()}
function stat(label,value,note,ic,amber=false){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-note"><span class="dot ${amber?'amber':''}"></span>${note}</div></div>`}
function dashboard(){const data=view(),active=data.patients.filter(p=>!p.closed&&hoursSince(p)<72),visits=data.visits.filter(v=>v.date===today()),open=data.alerts.filter(a=>a.status!=='resolved'),done=visits.filter(v=>v.status==='completed');let stats=isNurse()?[['Active patients',active.length,'In their first 72 hours','users'],["Today's visits",visits.length,`${done.length} completed so far`,'calendar'],['Available caregivers',state.caregivers.filter(c=>c.available).length,'Ready to make a difference','heart'],['Needs attention',open.length,open.length?'Your follow-up makes a difference':'All concerns are resolved','bell',!!open.length]]:session.role==='caregiver'?[['My patients',data.patients.length,'Connected to your care','users'],["Today's visits",visits.length,`${done.length} completed so far`,'calendar'],['Completed tasks',visits.reduce((n,v)=>n+v.tasks.length,0),'Every small step counts','checkcircle'],['Open concerns',open.length,'Shared with the care team','bell',!!open.length]]:[['Hours at home',Math.min(72,hoursSince(data.patients[0])),'One step at a time','home'],['Your visits',data.visits.length,'Support on your schedule','calendar'],['Completed visits',done.length,'Your team is here for you','heart'],['Open concerns',open.length,'Your nurse is here to help','message',!!open.length]];
return heading(`Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${session.name.split(' ')[0]} <span style="font-size:22px">☀</span>`,isNurse()?"Here's how your patients are settling in at home.":session.role==='caregiver'?"A little support can make someone's whole day.":"You're home. Your care team is still right here.",`<span class="btn secondary-action">${icon('calendar')}${dateText(today(),{month:'short',day:'numeric',year:'numeric'})}</span>${isNurse()?button(`${icon('plus')} New referral`,'new-referral'):button(`${icon('calendar')} My visits`,'nav','primary','data-id="visits"')}`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('leaf')} CONNECTED CARE, CLOSE TO HOME</div><h2>${session.role==='patient'?'Your next chapter starts at home.':'The journey home starts with you.'}</h2><p>${isNurse()?`${active.length} patients. One connected team. A little peace of mind in the first 72 hours.`:session.role==='caregiver'?'Your visits bring comfort, confidence, and a familiar face.':'A clear plan, a helping hand, and your care team by your side.'}</p><button class="hero-link" data-action="nav" data-id="patients">${session.role==='patient'?'See your care plan':'Meet the people in your care'} ${icon('arrow')}</button></div>${art()}</section><div class="stats">${stats.map(s=>stat(...s)).join('')}</div><div class="dashboard-grid"><div class="main-column"><section class="panel"><div class="panel-header"><div><h3>Today's visits <span class="badge-num">${visits.length}</span></h3><p>A familiar face. Right when it's needed.</p></div><button class="text-btn" data-action="nav" data-id="visits">View all ${icon('arrow')}</button></div><div class="tabs">${[['all','All visits'],['scheduled','Upcoming'],['completed','Completed']].map(([id,label])=>`<button data-action="visit-filter" data-id="${id}" class="${visitFilter===id?'active':''}">${label}</button>`).join('')}</div>${visitTable(visits.filter(v=>visitFilter==='all'||v.status===visitFilter))}<div class="table-footer"><span>All times shown in your local time</span><span>${done.length} of ${visits.length} visits complete</span></div></section><section class="panel"><div class="panel-header"><div><h3>${session.role==='patient'?'Your care journey':'Patients in your care'}</h3><p>Every transition has a person at its heart.</p></div><button class="text-btn" data-action="nav" data-id="patients">${session.role==='patient'?'View plan':'View all'} ${icon('arrow')}</button></div><div class="mini-patients">${data.patients.slice(0,3).map(p=>`<div class="mini-patient">${person(p,p.reason)}<button class="text-btn" data-action="patient" data-id="${p.id}">${Math.min(72,hoursSince(p))} of 72 hrs ${icon('chevron')}</button></div>`).join('')}</div></section></div><aside class="right-column">${insightPanel(data)}${progressPanel(data.patients[0])}<section class="panel"><div class="panel-header"><h3>Recent activity</h3><span class="dot"></span></div>${activityList(data.events.slice(0,3))}</section></aside></div>`}
function visitTable(visits){if(!visits.length)return empty('No visits here yet','Your next scheduled visit will appear here.','calendar');return `<div class="table-scroll"><table><thead><tr><th>${session.role==='patient'?'Caregiver':'Patient'}</th><th>Visit time</th><th>Status</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${[...visits].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(v=>`<tr><td>${session.role==='patient'?person(cById(v.caregiverId),'Home support visit'):person(pById(v.patientId),cById(v.caregiverId)?.name||'Unassigned')}</td><td><span style="color:#52664b;font-weight:500">${timeText(v.time)}</span><small style="display:block;font-size:9px;margin-top:4px;color:#98a08e">${v.date===today()?'Today':dateText(v.date)} · ${v.duration} min</small></td><td>${status(v.status)}</td><td><button class="icon-btn" data-action="visit" data-id="${v.id}" aria-label="Open visit for ${escape(pById(v.patientId)?.name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`}
function insightPanel(data){const alerts=data.alerts.filter(a=>a.status!=='resolved'),p=data.patients.find(p=>p.id===alerts[0]?.patientId)||data.patients[0];return `<section class="panel insight"><div class="panel-header"><h3><span class="sparkle-box">${icon('sparkles')}</span>Care insights</h3><span class="tiny-label">AI PREVIEW</span></div><div class="insight-body"><h4>${alerts.length?'A small nudge, a meaningful difference.':'The full picture, in a few words.'}</h4><p>${alerts.length?`${escape(pById(alerts[0].patientId)?.name.split(' ')[0])} has an open concern: ${escape(alerts[0].title.toLowerCase())}. A care team follow-up is still needed.`:'Bring the discharge handoff and latest home updates together in one easy-to-read summary.'}</p><div class="insight-note">${icon('info')}Source-based demo summary. Clinical review required; no live AI model connected.</div>${p?button(`Review care summary ${icon('arrow')}`,'summary','','data-id="'+p.id+'"'):''}</div></section>`}
function progressPanel(p){if(!p)return '';const elapsed=Math.min(72,hoursSince(p));return `<section class="panel"><div class="panel-header"><h3>The first 72 hours</h3>${icon('home')}</div><div class="progress-patient">${person(p,'A supported transition home')}<div class="progress-label"><span>Recovery journey</span><strong>${elapsed} / 72 hrs</strong></div><div class="progress-track" role="progressbar" aria-label="Hours since discharge" aria-valuenow="${elapsed}" aria-valuemin="0" aria-valuemax="72"><span style="width:${elapsed/72*100}%"></span></div><div class="milestones"><span>Home</span><span>24h</span><span>48h</span><span>72h</span></div><div class="mini-note">${icon('heart')}${p.caregiver?'Connected to a caregiver':'Caregiver assignment pending'}</div></div></section>`}
function activityList(events){return events.length?`<div class="activity-list">${[...events].sort((a,b)=>b.at.localeCompare(a.at)).map(e=>`<div class="activity"><span class="activity-icon">${icon(e.title.includes('concern')||e.title.includes('notified')?'bell':'check')}</span><strong>${escape(e.title)}</strong><p class="break-text">${escape(e.detail)}</p><small>${escape(e.author)} · ${relative(e.at)}</small></div>`).join('')}</div>`:empty('A fresh start','Updates from your care team will appear here.','heart')}
function empty(title,sub,ic='users'){return `<div class="empty">${icon(ic)}<strong>${title}</strong>${sub}</div>`}
function patientsPage(){if(session.role==='patient'&&page!=='search'){selectedPatient=session.personId;return detailPage()}let patients=view().patients;const base=patients.length;if(search)patients=patients.filter(p=>(p.name+' '+p.reason+' '+p.needs).toLowerCase().includes(search.toLowerCase()));if(filter==='unassigned')patients=patients.filter(p=>!p.caregiver);if(filter==='attention')patients=patients.filter(p=>state.alerts.some(a=>a.patientId===p.id&&a.status!=='resolved'));if(filter==='active')patients=patients.filter(p=>!p.closed&&hoursSince(p)<72);return heading(page==='search'?'Search results':session.role==='caregiver'?'My patients':'People in your care',`${base} ${base===1?'person':'people'}, each with their own journey home.`,isNurse()?button(`${icon('plus')} New referral`,'new-referral'):'')+(search?`<p class="search-summary">${patients.length} result${patients.length===1?'':'s'} for “${escape(search)}” <button class="text-btn" data-action="clear-search">Clear search</button></p>`:'')+`<div class="filters">${[['all','All patients'],['active','Within 72 hours'],['attention','Needs attention'],...(isNurse()?[['unassigned','Awaiting caregiver']]:[])].map(([id,label])=>`<button class="filter-pill ${filter===id?'active':''}" data-action="filter" data-id="${id}">${label}</button>`).join('')}</div><div class="patient-grid">${patients.map(p=>`<button class="patient-card" data-action="patient" data-id="${p.id}"><div class="patient-card-top">${avatar(p,'lg')}${state.alerts.some(a=>a.patientId===p.id&&a.status!=='resolved')?status('attention','Needs attention'):p.closed?status('completed','Handoff complete'):status(p.caregiver?'completed':'scheduled',p.caregiver?'Connected':'Awaiting match')}</div><h3>${escape(p.name)}</h3><p>${p.age} years · ${escape(p.reason)}</p><div class="progress-label"><span>First 72 hours</span><strong>${Math.min(72,hoursSince(p))} / 72 hrs</strong></div><div class="progress-track"><span style="width:${Math.min(100,hoursSince(p)/72*100)}%"></span></div><div class="card-caregiver">${p.caregiver?person(cById(p.caregiver),'Assigned caregiver','sm'):'Caregiver assignment pending'}${icon('chevron')}</div></button>`).join('')}</div>${patients.length?'':empty('No matching patients','Try another filter or search term.')}`}
function visitsPage(){const data=view();return heading(session.role==='caregiver'?'Make every visit count.':'Visits, all in one place.','A clear schedule for a smoother transition home.',isNurse()?button(`${icon('plus')} Schedule visit`,'schedule'):'')+`<section class="panel"><div class="panel-header"><h3>Visit schedule <span class="badge-num">${data.visits.length}</span></h3></div><div class="tabs">${[['all','All visits'],['scheduled','Upcoming'],['in-progress','In progress'],['completed','Completed']].map(([id,label])=>`<button data-action="visit-filter" data-id="${id}" class="${visitFilter===id?'active':''}">${label}</button>`).join('')}</div>${visitTable(data.visits.filter(v=>visitFilter==='all'||v.status===visitFilter))}</section>`}
function detailPage(){const p=view().patients.find(p=>p.id===selectedPatient);if(!p)return empty('Patient unavailable','This patient is not assigned to your demo profile.');const data=view(),visits=data.visits.filter(v=>v.patientId===p.id),alerts=data.alerts.filter(a=>a.patientId===p.id&&a.status!=='resolved');return `${session.role!=='patient'?'<button class="back-link" data-action="nav" data-id="patients">'+icon('left')+'Back to patients</button>':''}<div class="page-heading"><div class="detail-profile" style="margin-bottom:0">${avatar(p,'xl')}<div><div class="eyebrow">${session.role==='patient'?'YOUR CARE PLAN':'PATIENT OVERVIEW'}</div><h1>${escape(p.name)}</h1><p>${p.age} years · ${escape(p.reason)} · ${escape(p.language)}</p></div></div><div class="heading-actions">${button(`${icon('sparkles')} Care summary`,'summary','soft',`data-id="${p.id}"`)}</div></div>${alerts.length?`<div class="attention-strip">${icon('bell')}${alerts.length} concern${alerts.length>1?'s':''} awaiting follow-up<button class="text-btn" data-action="nav" data-id="alerts">Review ${icon('arrow')}</button></div>`:''}<div class="detail-layout"><div class="section-stack"><section class="panel"><div class="panel-header"><h3>${icon('file')}Discharge handoff</h3>${isNurse()?'<button class="text-btn" data-action="edit-plan" data-id="'+p.id+'">Edit plan</button>':''}</div><div class="info-grid"><div><div class="info-label">Arrived home</div><div class="info-value">${dateText(p.discharged,{month:'long',day:'numeric'})} · ${new Date(p.discharged).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</div></div><div><div class="info-label">Follow-up</div><div class="info-value break-text">${escape(p.followup)}</div></div><div class="info-full"><div class="info-label">Support needed</div><div class="info-value break-text">${escape(p.needs)}</div></div><div class="info-full"><div class="info-label">Approved care instructions</div><div class="info-value break-text">${escape(p.plan)}</div><div class="source">${icon('shield')}Source: hospital handoff · ${dateText(p.updated||p.created)} · Fictional demo record</div></div></div></section><section class="panel"><div class="panel-header"><h3>${icon('calendar')}Home visits</h3>${isNurse()?'<button class="text-btn" data-action="schedule" data-id="'+p.id+'">Schedule visit '+icon('plus')+'</button>':''}</div>${visitTable(visits)}</section><section class="panel"><div class="panel-header"><h3>Care timeline</h3></div>${activityList(data.events.filter(e=>e.patientId===p.id))}</section></div><aside class="section-stack">${progressPanel(p)}<section class="panel"><div class="panel-header"><h3>Your care team</h3></div><div style="padding:0 22px 22px">${person(profiles.nurse,'Nurse coordinator')}<div style="height:20px"></div>${p.caregiver?person(cById(p.caregiver),cById(p.caregiver)?.role):'<p class="info-value">A caregiver has not been assigned yet.</p>'}${isNurse()?button(`${icon('users')} ${p.caregiver?'Change caregiver':'Assign caregiver'}`,'assign','','style="margin-top:20px;width:100%" data-id="'+p.id+'"'):''}</div></section><section class="panel"><div class="panel-header"><h3>Need a helping hand?</h3></div><div class="plain-copy">Share a question or practical concern with your care team.${button(`${icon('message')} Raise a concern`,'concern','soft',`data-id="${p.id}" style="width:100%;margin-top:15px"`)}<p style="font-size:10px;margin-top:12px;color:#9ba48d">Demo inbox only. For an emergency, contact local emergency services directly.</p></div></section>${isNurse()?`<section class="panel"><div class="panel-header"><h3>Transition handoff</h3></div><div class="plain-copy">${p.closed?'Handoff recorded. Review the care timeline for the next care owner.':'Finish the 72-hour episode with a named next contact and any continuing support needs.'}${!p.closed?button('Complete handoff','handoff','',`data-id="${p.id}" style="margin-top:12px;width:100%"`):''}</div></section>`:''}</aside></div>`}
function teamPage(){const caregivers=isNurse()?state.caregivers:state.caregivers.filter(c=>c.id===session.personId);return heading('Good people. Connected care.','The people making the first days at home a little easier.')+`<div class="banner">${icon('shield')}Demo profiles and qualifications. Student visits require the listed clinical supervisor.</div><div class="team-grid">${caregivers.map(c=>`<section class="panel team-card"><div style="display:flex;justify-content:space-between;align-items:flex-start">${avatar(c,'xl')}${status(c.available?'completed':'scheduled',c.available?'Available':'Unavailable')}</div><h3>${escape(c.name)}</h3><p>${escape(c.role)}</p><div class="team-info"><div>${icon('message')}${escape(c.language)}</div><div>${icon('heart')}${escape(c.experience)}</div><div>${icon('users')}${state.patients.filter(p=>p.caregiver===c.id).length} assigned patients</div><div>${icon('shield')}Supervisor: ${escape(c.supervisor)}</div></div>${isNurse()?button('View assigned patients','caregiver-patients','',`data-id="${c.id}"`):button('View my visits','nav','','data-id="visits"')}</section>`).join('')}</div>`}
function alertsPage(){const data=view();const alerts=data.alerts.filter(a=>filter!=='resolved'?a.status!=='resolved':a.status==='resolved');return heading(isNurse()?'A little attention goes a long way.':'Your concerns, heard.','Track every concern from the first note to the next step.',button(`${icon('plus')} Raise a concern`,'concern'))+`<div class="filters"><button class="filter-pill ${filter!=='resolved'?'active':''}" data-action="filter" data-id="all">Open concerns (${data.alerts.filter(a=>a.status!=='resolved').length})</button><button class="filter-pill ${filter==='resolved'?'active':''}" data-action="filter" data-id="resolved">Resolved</button></div><section class="panel">${alerts.length?alerts.map(a=>`<article class="alert-card"><div class="alert-top"><span style="color:#b79b5c">${icon('bell')}</span><h4>${escape(a.title)}</h4>${status(a.status)}</div><p class="break-text">${escape(a.detail)}</p>${a.resolution?`<div class="summary-block" style="margin-top:12px"><h4>Follow-up recorded</h4><p>${escape(a.resolution)}</p></div>`:''}<small>${escape(pById(a.patientId)?.name)} · Reported by ${escape(a.author)} · ${relative(a.created)}</small><div class="alert-actions">${button('View patient','patient','small',`data-id="${a.patientId}"`)}${isNurse()&&a.status==='new'?button('Acknowledge','acknowledge','small soft',`data-id="${a.id}"`):''}${isNurse()&&a.status!=='resolved'?button('Record follow-up','resolve','small primary',`data-id="${a.id}"`):''}</div></article>`).join(''):empty(filter==='resolved'?'No resolved concerns yet':"You're all caught up.",filter==='resolved'?'Completed follow-ups will be saved here.':'There are no open concerns in your care workspace.','checkcircle')}</section>`}
function settingsPage(){return heading('Your workspace','A few details about your CareBridge experience.')+`<section class="panel"><div class="settings-row">${person(session,session.title,'lg')}${button('Change demo profile','logout')}</div><div class="settings-row"><div><h4>Demo data & privacy</h4><p>All people and records are fictional. Data is saved only in this browser. Demo profiles illustrate permissions; they are not authenticated accounts. Do not enter real patient information.</p></div>${icon('shield')}</div><div class="settings-row"><div><h4>AI care summaries</h4><p>Summaries combine the discharge handoff, latest caregiver note, and open concerns using a local template. No live AI model is connected. Source records are shown for human review.</p></div><span class="tiny-label">DEMO</span></div><div class="settings-row"><div><h4>Alerts & notifications</h4><p>Concerns appear inside this demo. No emails, text messages, or emergency notifications are sent.</p></div>${icon('bell')}</div><div class="settings-row"><div><h4>Start with a fresh demo</h4><p>Restore the fictional patients, visits, and care team. This removes the changes you've made in this browser.</p></div>${button('Reset demo','reset','')}</div></section>`}
function showModal(title,subtitle,body,footer='',formId=''){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${formId?`<form id="${formId}">`:''}<div class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body"><div id="form-error" role="alert"></div>${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}${formId?'</form>':''}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('#overlay input, #overlay select, #overlay textarea, #overlay button')?.focus(),0)}
function closeModal(){ $('#overlay').innerHTML='';document.body.classList.remove('modal-open');lastFocus?.focus(); }
const actions=(label='Save')=>'<button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">'+label+'</button>';
const field=(label,name,type='text',value='',full=false,required=true)=>`<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${escape(value)}" ${required?'required':''} ${type==='text'?'maxlength="180"':''}></div>`;
const textfield=(label,name,value='',required=true)=>`<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="2500" ${required?'required':''}>${escape(value)}</textarea></div>`;
const patientSelect=(id='')=>`<div class="field full"><label for="f-patientId">Patient</label><select id="f-patientId" name="patientId" required><option value="">Choose a patient</option>${view().patients.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${escape(p.name)}</option>`).join('')}</select></div>`;
function referralModal(){showModal('A supported start at home','Create a discharge referral using fictional information.',`<div class="form-grid">${field('Patient name','name')}${field('Age','age','number')}${field('Preferred language','language','text','English')}${field('Discharged at','discharged','datetime-local',today()+'T09:00')}${field('Reason for support','reason','text','',true)}${textfield('Practical support needed','needs')}${textfield('Hospital-approved care instructions','plan')}${field('Follow-up plan','followup','text','',true)}</div>`,actions('Create referral'),'referral-form');$('#f-age').min='18';$('#f-age').max='120'}
function scheduleModal(id=''){showModal('Make room for a little care','Choose an assigned patient and a visit time. Visits last 60 minutes.',`<div class="form-grid">${patientSelect(id)}${field('Date','date','date',today())}${field('Start time','time','time','10:00')}<p class="form-hint field full">The patient’s assigned caregiver will attend. Assign a caregiver on the patient page first. Overlapping visits are prevented.</p></div>`,actions('Schedule visit'),'schedule-form');$('#f-date').min=today()}
function assignModal(id){const p=pById(id);showModal('Connect a caregiver',`Arrange practical support for ${escape(p.name)}.`,`<input type="hidden" name="patientId" value="${id}"><div class="field"><label for="f-caregiverId">Available caregiver</label><select id="f-caregiverId" name="caregiverId" required><option value="">Choose a caregiver</option>${state.caregivers.filter(c=>c.available).map(c=>`<option value="${c.id}" ${p.caregiver===c.id?'selected':''}>${escape(c.name)} · ${escape(c.role)}</option>`).join('')}</select><p class="form-hint" style="margin-top:10px">Confirm that support needs fit the caregiver’s role. CNA students are supervised by Emma Davis, RN. Reassignment is blocked while a visit is in progress; upcoming visits transfer if the new caregiver is free.</p></div>`,actions('Confirm assignment'),'assign-form')}
function summaryModal(id){const s=summaryFor(view(),id);if(!s)return;showModal(s.heading,'Context summary · demo template, with sources.',`<div class="banner">${icon('sparkles')}This preview organizes recorded information. No live AI model is connected; review the source details before making decisions.</div><div class="summary-block"><h4>Support at home</h4><p>${escape(s.support)}</p></div><div class="summary-block"><h4>Latest caregiver update</h4><p>${escape(s.update)}</p></div><div class="summary-block"><h4>Next step</h4><p>${escape(s.next)}</p></div><div class="source-list"><strong>Information used</strong>${s.sources.map((s,i)=>`<div>${i+1}. ${escape(s.label)} · ${dateText(s.date)}</div>`).join('')}</div>`,button('Open patient record','patient','primary',`data-id="${id}"`))}
function concernModal(id=''){showModal('Share a concern','Your note appears in the nurse’s demo inbox.',`<div class="form-grid">${patientSelect(id)}${field('What needs attention?','title','text','',true)}${textfield('What happened or what support is needed?','detail')}<div class="banner field full" style="margin-bottom:0">${icon('info')}This demo does not send real notifications. For immediate danger, contact local emergency services directly.</div></div>`,actions('Share with care team'),'concern-form')}
function visitModal(id){const v=view().visits.find(v=>v.id===id);if(!v)return;const p=pById(v.patientId),editable=session.role==='caregiver'&&v.caregiverId===session.personId&&['scheduled','in-progress'].includes(v.status);showModal(`Visit with ${escape(p.name.split(' ')[0])}`,`${dateText(v.date)} at ${timeText(v.time)} · ${v.duration} minutes · ${escape(cById(v.caregiverId)?.name)}`,`<input type="hidden" name="visitId" value="${id}"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px">${person(p,p.reason)}${status(v.status)}</div><div class="summary-block"><h4>Approved support</h4><p>${escape(p.needs)}</p><p style="margin-top:8px">${escape(p.plan)}</p></div><div class="task-list" style="padding:0">${TASKS.map((t,i)=>`<label class="task ${v.tasks.includes(i)?'checked':''}"><input type="checkbox" name="task" value="${i}" ${v.tasks.includes(i)?'checked':''} ${editable?'':'disabled'}><span>${t}</span></label>`).join('')}</div><div class="field" style="margin-top:18px"><label for="f-note">Caregiver visit note</label><textarea id="f-note" name="note" placeholder="Record what you observed and what the patient reported…" maxlength="2500" ${editable?'':'readonly'}>${escape(v.note)}</textarea><p class="form-hint">Record facts and reported concerns. Incomplete tasks can be explained in your note.</p></div>${editable?'<label class="form-check" style="margin-top:15px"><input type="checkbox" name="concern"> Flag this update for the nurse to review</label>':''}${v.status==='completed'?'<p class="source" style="margin-top:15px">'+icon('shield')+'Caregiver observation · '+escape(cById(v.caregiverId)?.name)+'</p>':''}`,editable?`<button type="submit" name="intent" value="draft" class="btn">Save progress</button><button type="submit" name="intent" value="complete" class="btn primary">${icon('check')} Complete visit</button>`:`${button('View patient','patient','',`data-id="${p.id}"`)}${isNurse()&&v.status==='scheduled'?button('Cancel visit','cancel-visit','',`data-id="${v.id}"`):''}${button('Care summary','summary','primary',`data-id="${p.id}"`)}`,'visit-form')}
function formError(message){$('#form-error').innerHTML=`<div class="form-error">${escape(message)}</div>`;$('#form-error').scrollIntoView({block:'nearest'})}
function saveAndRender(message){persist();closeModal();render();toast(message)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;if(action==='select-role'){loginRole=id;login();return}if(action==='login'){session={...profiles[loginRole]};sessionStorage.setItem('carebridge-session',JSON.stringify(session));page='overview';filter='all';search='';persist();render();return}if(action==='close-modal'){closeModal();return}if(!session)return;const nurseActions=['new-referral','schedule','assign','acknowledge','resolve','edit-plan','handoff','cancel-visit'];if(nurseActions.includes(action)&&!isNurse())return;
 if(action==='nav'){closeModal();page=id;filter='all';search='';visitFilter='all';mobileOpen=false;render();window.scrollTo(0,0)}
 else if(action==='logout'){closeModal();session=null;sessionStorage.removeItem('carebridge-session');mobileOpen=false;login()}
 else if(action==='toggle-menu'){mobileOpen=!mobileOpen;render()}
 else if(action==='patient'){if(!view().patients.some(p=>p.id===id))return;closeModal();selectedPatient=id;page='detail';mobileOpen=false;render();window.scrollTo(0,0)}
 else if(action==='filter'){filter=id;render()}
 else if(action==='visit-filter'){visitFilter=id;render()}
 else if(action==='clear-search'){search='';page='patients';render()}
 else if(action==='new-referral')referralModal();
 else if(action==='schedule')scheduleModal(id||'');
 else if(action==='assign')assignModal(id);
 else if(action==='summary')summaryModal(id);
 else if(action==='concern')concernModal(id||session.role==='patient'&&session.personId||'');
 else if(action==='visit')visitModal(id);
 else if(action==='acknowledge'){const a=state.alerts.find(a=>a.id===id);a.status='acknowledged';event(state,a.patientId,'Concern acknowledged',a.title,session.name);saveAndRender('Concern acknowledged. The next step is yours.');}
 else if(action==='resolve'){const a=state.alerts.find(a=>a.id===id);showModal('Record the next step',escape(a.title),`<input type="hidden" name="alertId" value="${id}">${textfield('Action taken and follow-up owner','resolution')}<p class="form-hint" style="margin-top:12px">Record what was done and who is responsible for any ongoing follow-up.</p>`,actions('Resolve concern'),'resolve-form')}
 else if(action==='edit-plan'){const p=pById(id);showModal('Update the care plan','Changes appear in the patient and assigned caregiver views.',`<input type="hidden" name="patientId" value="${id}"><div class="form-grid">${textfield('Practical support needed','needs',p.needs)}${textfield('Hospital-approved instructions','plan',p.plan)}${field('Follow-up plan','followup','text',p.followup,true)}</div>`,actions('Save care plan'),'plan-form')}
 else if(action==='handoff'){showModal('A thoughtful next step','Record who takes over care after this transition.',`<input type="hidden" name="patientId" value="${id}">${textfield('Next care owner and continuing support plan','handoff')}`,actions('Complete handoff'),'handoff-form')}
 else if(action==='cancel-visit'){const v=state.visits.find(v=>v.id===id);showModal('Cancel this visit?',`${escape(pById(v.patientId)?.name)} · ${dateText(v.date)} at ${timeText(v.time)}`,`<input type="hidden" name="visitId" value="${id}">${textfield('Cancellation reason and replacement plan','reason')}`,actions('Confirm cancellation'),'cancel-form')}
 else if(action==='caregiver-patients'){const c=cById(id),patients=state.patients.filter(p=>p.caregiver===id);showModal(`${escape(c.name)}’s patients`,'Current caregiver assignments.',patients.length?patients.map(p=>`<div class="mini-patient">${person(p,p.reason)}${button('View','patient','small',`data-id="${p.id}"`)}</div>`).join(''):empty('No assigned patients','Assign a patient from their care record.'))}
 else if(action==='reset')showModal('Start fresh?','Your browser’s demo changes will be removed.','<p class="info-value">This restores the original fictional patients, caregivers, notes, and visits for all demo profiles in this browser.</p>',actions('Reset demo'),'reset-form');
});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id==='search-form'){search=$('#global-search').value.trim();page='search';filter='all';render();return}const data=new FormData(form),get=name=>String(data.get(name)||'').trim();const nurseForms=['referral-form','schedule-form','assign-form','resolve-form','plan-form','handoff-form','cancel-form'];if(nurseForms.includes(form.id)&&!isNurse())return;
if(form.id==='referral-form'){if(!get('name')||!get('needs')||!get('plan')||!get('reason')||!get('followup'))return formError('Please complete the referral details.');const discharged=new Date(get('discharged'));if(discharged>new Date())return formError('Discharge time cannot be in the future.');const id=crypto.randomUUID();state.patients.unshift({id,name:get('name'),age:Number(get('age')),reason:get('reason'),needs:get('needs'),plan:get('plan'),followup:get('followup'),language:get('language'),discharged:discharged.toISOString(),created:new Date().toISOString(),caregiver:null,initials:initials(get('name')),color:'mint',closed:false,contact:'Demo care team · (555) 010-0072'});event(state,id,'New referral received',`${get('name')} is ready for a caregiver assignment.`,session.name);selectedPatient=id;page='detail';saveAndRender('Referral created. Assign a caregiver to take the next step.');}
else if(form.id==='assign-form'){const p=pById(get('patientId')),c=cById(get('caregiverId'));if(!p||!c||!c.available)return formError('Please choose an available caregiver.');const visits=state.visits.filter(v=>v.patientId===p.id&&v.status==='scheduled');if(state.visits.some(v=>v.patientId===p.id&&v.status==='in-progress'))return formError('Finish the active visit before changing caregivers.');if(visits.some(v=>hasConflict(state,c.id,v.date,v.time,v.duration,v.id)))return formError('This caregiver has an overlapping visit. Choose another caregiver or cancel and reschedule the conflicting visit.');p.caregiver=c.id;for(const v of visits)v.caregiverId=c.id;event(state,p.id,'Caregiver assigned',`${c.name} is assigned. Supervisor: ${c.supervisor}.`,session.name);saveAndRender('Caregiver assigned. Upcoming visits have been updated.');}
else if(form.id==='schedule-form'){const p=pById(get('patientId'));if(!p?.caregiver)return formError('Assign a caregiver on the patient page before scheduling.');if(p.closed)return formError('This transition has been handed off. Use an active referral.');if(new Date(get('date')+'T'+get('time'))<new Date())return formError('Choose a future date and time.');if(hasConflict(state,p.caregiver,get('date'),get('time')))return formError('The caregiver already has a visit at this time. Choose a different time.');state.visits.push({id:crypto.randomUUID(),patientId:p.id,caregiverId:p.caregiver,date:get('date'),time:get('time'),duration:60,status:'scheduled',tasks:[],note:''});event(state,p.id,'Home visit scheduled',`${cById(p.caregiver).name} · ${dateText(get('date'))} at ${timeText(get('time'))}.`,session.name);saveAndRender('Visit scheduled. It is now on the shared timeline.');}
else if(form.id==='visit-form'){const v=state.visits.find(v=>v.id===get('visitId'));if(session.role!=='caregiver'||v?.caregiverId!==session.personId||!['scheduled','in-progress'].includes(v.status))return;const complete=e.submitter?.value==='complete';if(complete&&!get('note'))return formError('Add a brief visit note before completing the visit.');if(data.has('concern')&&!get('note'))return formError('Describe the concern in the visit note.');v.tasks=data.getAll('task').map(Number).filter(x=>x>=0&&x<TASKS.length);v.note=get('note');v.status=complete?'completed':'in-progress';v.updated=new Date().toISOString();event(state,v.patientId,complete?'Home visit completed':'Visit progress saved',`${v.tasks.length} of ${TASKS.length} tasks recorded. ${v.note||'Visit in progress.'}`,session.name);if(data.has('concern')){const existing=state.alerts.find(a=>a.visitId===v.id&&a.status!=='resolved');if(existing){existing.detail=v.note;existing.status='new'}else state.alerts.unshift({id:crypto.randomUUID(),visitId:v.id,patientId:v.patientId,title:'Caregiver requests nurse review',detail:v.note,status:'new',created:new Date().toISOString(),author:session.name,resolution:''});event(state,v.patientId,'Care team notified','Caregiver requested review of the visit update.',session.name)}saveAndRender(complete?'Visit complete. Your update is ready for the nurse.':'Progress saved. You can continue this visit later.');}
else if(form.id==='concern-form'){if(!view().patients.some(p=>p.id===get('patientId'))||!get('title')||!get('detail'))return formError('Choose a patient and describe the concern.');state.alerts.unshift({id:crypto.randomUUID(),patientId:get('patientId'),title:get('title'),detail:get('detail'),status:'new',created:new Date().toISOString(),author:session.name,resolution:''});event(state,get('patientId'),'Concern shared with care team',get('title'),session.name);saveAndRender('Concern added to the nurse’s demo inbox.');}
else if(form.id==='resolve-form'){if(!get('resolution'))return formError('Record the follow-up before resolving this concern.');const a=state.alerts.find(a=>a.id===get('alertId'));a.status='resolved';a.resolution=get('resolution');a.resolvedAt=new Date().toISOString();event(state,a.patientId,'Concern resolved',a.resolution,session.name);saveAndRender('Follow-up recorded. Concern resolved.');}
else if(form.id==='plan-form'){if(!get('needs')||!get('plan')||!get('followup'))return formError('Please complete the care instructions and follow-up plan.');const p=pById(get('patientId'));p.needs=get('needs');p.plan=get('plan');p.followup=get('followup');p.updated=new Date().toISOString();event(state,p.id,'Care plan updated','Hospital instructions and follow-up details were reviewed.',session.name);saveAndRender('Care plan updated for the patient and caregiver.');}
else if(form.id==='handoff-form'){const p=pById(get('patientId'));if(!get('handoff'))return formError('Add the next care owner and support plan.');if(state.alerts.some(a=>a.patientId===p.id&&a.status!=='resolved'))return formError('Resolve outstanding concerns before completing the handoff.');if(state.visits.some(v=>v.patientId===p.id&&['scheduled','in-progress'].includes(v.status)))return formError('Complete or cancel outstanding visits before finishing the handoff.');p.closed=true;event(state,p.id,'Transition handed off',get('handoff'),session.name);saveAndRender('Handoff saved with the next care owner.');}
else if(form.id==='cancel-form'){if(!get('reason'))return formError('Add a cancellation reason and replacement plan.');const v=state.visits.find(v=>v.id===get('visitId'));v.status='cancelled';event(state,v.patientId,'Visit cancelled',get('reason'),session.name);saveAndRender('Visit cancelled. The reason is saved in the care timeline.');}
else if(form.id==='reset-form'){state=seed();page='overview';selectedPatient=null;filter='all';visitFilter='all';search='';saveAndRender('Demo restored. A fresh start.');}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#overlay .modal')){const focusable=[...$('#overlay .modal').querySelectorAll('button:not(:disabled),input:not(:disabled):not([type="hidden"]),select:not(:disabled),textarea:not(:disabled),a[href]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
document.addEventListener('change',e=>{if(e.target.matches('.task input'))e.target.closest('.task').classList.toggle('checked',e.target.checked)});
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=JSON.parse(e.newValue);if(next?.version===VERSION){state=next;if(!$('#overlay .modal'))render();else toast('Care data changed in another tab. Close and reopen this form before editing.')}}catch{}}});
render();
